const UI4={lang:'zh',theme:'warm',view:'home',id:'start',lab:'',search:'',help:false,notes:{},done:[],run:true};
try{let raw=JSON.parse(localStorage.getItem('zth-client-v4')||localStorage.getItem('zerotohand-academy-v2')||'{}');Object.assign(UI4,raw);UI4.done=Array.isArray(raw.done)?raw.done.filter(id=>LESSONS.some(l=>l.id===id)):[];UI4.notes={};for(let l of LESSONS)if(typeof raw.notes?.[l.id]==='string')UI4.notes[l.id]=raw.notes[l.id].slice(0,20000);}catch{}
if(!['zh','en'].includes(UI4.lang))UI4.lang='zh';if(!['warm','light','dark'].includes(UI4.theme))UI4.theme='warm';UI4.view='home';UI4.help=false;
const T=(zh,en)=>UI4.lang==='en'?en:zh,E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const LAB4={
 circuit:['第一条LED电路','Your first LED circuit','circuit'],meter:['万用表与同一条回路','Meter on the same circuit','circuit'],power:['电源与限流','Supply and current limit','circuit'],rc:['电容充放电','Capacitor charging','rc'],wave:['信号与示波器','Signal and oscilloscope','wave'],pwm:['PWM与电机','PWM and motor','pwm'],pid:['闭环控制','Feedback control','pid'],robot:['机械臂运动','Robot motion','robot'],thermal:['焊点热传递','Heat transfer','thermal'],bits:['UART逐位发送','UART bit by bit','bits'],cpu:['CPU单步执行','CPU single stepping','cpu'],vision:['像素与阈值','Pixels and threshold','vision'],rl:['网格世界学习','Grid-world learning','rl'],analog:['仪表加载误差','Meter loading','analog'],stencil:['锡膏印刷','Paste printing','stencil'],reflow:['温度曲线检查','Thermal profile check','reflow'],pcb:['PCB走线检查','PCB trace checks','pcb'],fault:['故障排查','Fault diagnosis','fault']};
const LM4={calc:'circuit',wiring:'circuit',scope:'wave',logic:'bits',iron:'thermal',hotair:'thermal'};
const FIELD4={v:['电源电压','Supply voltage','V'],r:['电阻','Resistance','Ω'],c:['电容','Capacitance','μF'],freq:['频率','Frequency','Hz'],amp:['峰值','Amplitude','V'],duty:['占空比','Duty cycle','%'],target:['目标','Target','%'],kp:['比例 Kp','Proportional Kp',''],ki:['积分 Ki','Integral Ki',''],kd:['微分 Kd','Derivative Kd',''],x:['目标 X','Target X','mm'],y:['目标 Y','Target Y','mm'],temp:['热源温度','Source temperature','°C'],mass:['热惯性','Thermal time constant','s'],byte:['数据字节','Data byte',''],rate:['播放速度','Playback speed','bit/s'],limit:['限流','Current limit','mA'],rm:['仪表内阻','Meter resistance','kΩ'],threshold:['阈值','Threshold',''],episodes:['训练回合','Training episodes',''],width:['线宽','Trace width','mm'],clearance:['间距','Clearance','mm'],thickness:['钢网厚度','Stencil thickness','mm'],aperture:['开口边长','Square aperture','mm'],peak:['峰值温度','Peak temperature','°C'],dwell:['液相线以上时间','Time above liquidus','s']};
let SIM4={},loop4=0,last4=0,active4=null;
function sim4(id){if(SIM4[id])return SIM4[id];let k=LAB4[id][2],s=STORY_META[k]?storyInitial(k):{kind:k,p:{},t:0,run:false,on:true,y:0,history:[]};s.run=!matchMedia('(prefers-reduced-motion: reduce)').matches;s.place='source';s.mode='voltage';s.jack='voltage';s.fuse=true;s.step=0;s.p.kd=0;s.previousY=0;s.filteredD=0;s.p.limit=20;s.p.rm=1000;s.p.threshold=128;s.p.episodes=100;s.p.width=.3;s.p.clearance=.25;s.p.thickness=.12;s.p.aperture=.6;s.p.peak=235;s.p.dwell=50;if(k==='cpu')s.cpu={program:Models.cpuParse(DEFAULT_ASM),pc:0,reg:[0,0,0,0],mem:Array(16).fill(0),zero:false,steps:0,halted:false};return SIM4[id]=s;}
function save4(){try{localStorage.setItem('zth-client-v4',JSON.stringify(UI4));}catch{document.getElementById('client-status').textContent=T('无法保存，请导出备份','Storage unavailable. Export a backup.');}}
function title4(l){return UI4.lang==='en'?EN_LESSONS[l.id]?.title||l.id:l.title;}
function label4(k){return T(...FIELD4[k]);}
function nav4(view,id){UI4.view=view;if(id){if(view==='lesson')UI4.id=id;if(view==='lab')UI4.lab=id;}history.replaceState(null,'','#'+view+(id?'/'+id:''));render4();window.scrollTo({top:0,behavior:'instant'});}
function card4(l){return `<button class="learn-card" data-lesson="${l.id}"><span>${levelLabel7(l)} · ${UI4.lang==='en'?l.time.replace('虚拟实验','Interactive lab').replace('项目规划','Project planning').replace('平台比较','Platform comparison').replace('项目工作流','Project workflow'):l.time.replace(' + practice',' + 实践')}</span><h3>${E(title4(l))}</h3><p>${E(UI4.lang==='en'?EN_LESSONS[l.id].idea:l.desc)}</p><b>${UI4.done.includes(l.id)?T('✓ 已完成','✓ Completed'):T('开始学习 →','Start learning →')}</b></button>`;}
function home4(){return `<section class="welcome4"><div><span class="overline">LEARN · TOUCH · UNDERSTAND</span><h1>${T('从一个“为什么”，<br>到亲手弄明白。','Start with a question.<br>Make the answer visible.')}</h1><p>${T('不需要先懂电路。按顺序认识元件、连接回路、观察现象，再用测量验证自己的判断。','No electronics background required. Meet the components, connect a circuit, observe what changes and test your prediction with measurements.')}</p><div class="row4"><button class="primary4" data-lesson="start">${T('从零开始 · 第1课','Start from zero · Lesson 1')}</button><button data-go="lab">${T('直接进入操作台','Explore the workbench')}</button></div></div><div class="welcome-note"><span>01 / 12</span><h2>${T('今天只学会一件事','One idea for today')}</h2><p>${T('电压存在，不代表一定有电流。点击右侧开关，看看断开回路之后发生什么。','Voltage can exist without current. Open the switch in the workbench and see what remains.')}</p><button data-lab="circuit">${T('试着断开回路 ↗','Try opening the circuit ↗')}</button></div></section><div class="section4"><h2>${T('你的零基础学习路线','Your beginner learning path')}</h2><span>${T('12课 · 按先修顺序 · 可随时复习','12 lessons · Ordered prerequisites · Revisit anytime')}</span></div><div class="route4">${LESSON_ROUTE.map((id,i)=>{let l=LESSONS.find(x=>x.id===id);return `<button data-lesson="${id}"><i>${String(i+1).padStart(2,'0')}</i><span>${E(title4(l))}</span><b>${UI4.done.includes(id)?'✓':'→'}</b></button>`;}).join('')}</div><div class="section4"><h2>${T('先动手，再读解释','Try it before reading the explanation')}</h2></div>${gallery5()}`;}
function courses4(){let list=LESSONS.filter(l=>(title4(l)+' '+l.id).toLowerCase().includes(UI4.search.toLowerCase()));return `<div class="section4"><div><span class="overline">${T('课程资料库','LEARNING LIBRARY')}</span><h1>${T('从基础到工程实践','From fundamentals to engineering')}</h1><p>${T('完全没有电脑基础，请从长期学习路线开始；已有基础可搜索专题，先核对本课先修知识。','Start with the long-term learning route if computers are new to you. Otherwise find a topic and check its prerequisites.')}</p></div></div><label class="search4">${T('搜索课程','Search lessons')}<input id="course-search4" value="${E(UI4.search)}" placeholder="${T('例如：电机、万用表、RC','Try motor, meter or RC')}"></label><div class="cards4">${list.map(card4).join('')}</div>`;}
const CHECK4={
 start:[9.09,'5 V、330 Ω、LED压降2 V时，电流是多少 mA？','At 5 V, 330 Ω and a 2 V LED drop, what is current in mA?'],
 kirchhoff:[2.5,'两个1 kΩ电阻串联接5 V，支路电流是多少 mA？','Two 1 kΩ resistors are in series across 5 V. What is the branch current in mA?'],
 components:[.25,'100 Ω电阻两端为5 V时，耗散功率是多少 W？','A 100 Ω resistor has 5 V across it. What power does it dissipate in W?'],
 'wiring-guide':[9.09,'5 V电源、2 V LED和330 Ω限流电阻串联，电流约是多少 mA？','A 5 V source, 2 V LED and 330 Ω resistor are in series. What is the current in mA?'],
 meter:[3,'电源5 V，串联LED压降2 V，电阻两端电压是多少 V？','A 5 V supply feeds a series LED with a 2 V drop. What is the voltage across the resistor in V?'],
 power:[3.65,'5 V电源给2 V LED串联330 Ω电阻，电流限值设为5 mA，恒流时输出约多少 V？','A 5 V source feeds a 2 V LED and 330 Ω resistor; the current limit is 5 mA. What is the output voltage in current limit, in V?'],
 rc:[1,'10 kΩ与100 μF的时间常数是多少秒？','What is the time constant in seconds for 10 kΩ and 100 μF?'],
 scope:[1000,'周期1 ms，对应多少 Hz？','A period of 1 ms corresponds to how many Hz?'],
 logic:[10,'UART一帧有1个起始位、8个数据位和1个停止位，共多少位？','A UART frame has one start bit, eight data bits and one stop bit. How many bits total?'],
 mcu:[1,'1 kHz定时器信号的周期是多少 ms？','What is the period in ms of a 1 kHz timer signal?'],
 'motor-control':[15.71,'0.5 N·m、300 rpm，对应机械功率约多少 W？','At 0.5 N·m and 300 rpm, what is mechanical power in W?'],
 robot:[220,'两根各110 mm的机械臂连杆，几何上最大可达距离是多少 mm？','Two robot links are each 110 mm long. What is their maximum geometric reach in mm?']
};
function lesson4(){let l=LESSONS.find(x=>x.id===UI4.id)||LESSONS[0],en=EN_LESSONS[l.id],deep=DEEP_LESSONS[l.id]||[],lab=LESSON_DEVICE5[l.id]||LM4[l.lab]||l.lab;if(!LAB4[lab])lab='circuit';let sections=UI4.lang==='en'?[['Build the mental model',en.idea],['Work through the numbers or procedure',en.example],['Check assumptions and common errors',en.error]]:l.sections;let quiz=CHECK4[l.id];return `<button class="back4" data-go="courses">← ${T('全部课程','All lessons')}</button><header class="lesson-title4"><span class="overline">${l.level} / ${UI4.lang==='en'?l.time.replace('虚拟实验','Interactive lab').replace('项目规划','Project planning').replace('平台比较','Platform comparison').replace('项目工作流','Project workflow'):l.time.replace(' + practice',' + 实践')}</span><h1>${E(title4(l))}</h1><p>${E(UI4.lang==='en'?en.idea:l.desc)}</p></header><div class="lesson-grid4"><article class="reading4"><div class="goal4"><h3>${T('这一课先完成什么','Your goal for this lesson')}</h3><p>${T('先说出输入和输出，再做一次只改变一个条件的实验，最后用读数解释结果。','Identify the input and output, change one condition, and explain the measured result.')}</p><p>${T('先修：','Before you begin: ')}${(l.prereq||[]).map(id=>{let p=LESSONS.find(x=>x.id===id);return p?`<button data-lesson="${id}">${E(title4(p))}</button>`:'';}).join(' ')||T('不需要先修知识','No prior knowledge required')}</p></div>${deep.map((a,i)=>`<section class="reading-section"><span class="step4">${String(i+1).padStart(2,'0')}</span><h2>${E(T(a[0],a[1]))}</h2><p>${E(T(a[2],a[3]))}</p></section>`).join('')}${sections.map(([a,b])=>`<section class="reading-section"><h2>${E(a)}</h2><p>${E(b)}</p></section>`).join('')}<div class="example4"><span class="overline">${T('例题推导','WORKED EXAMPLE')}</span><h3>${T('把数字一步一步代进去','Work through an example')}</h3><p>${E(UI4.lang==='en'?en.example:l.example)}</p></div><section class="practice4"><h2>${T('先预测，再验证','Predict, then verify')}</h2><ol><li>${T('保持其他条件不变，选择一个输入参数。','Choose one input and keep the other conditions fixed.')}</li><li>${T('在笔记写下你的预测和理由，再改变输入。','Write a prediction and reason before changing the input.')}</li><li>${T('比较动画、测量读数和公式；不一致时先核对模型假设。','Compare animation, measurement and equation; check assumptions if they disagree.')}</li></ol>${quiz?`<label>${E(T(quiz[1],quiz[2]))}<input type="number" step="any" id="answer4"></label><button data-check="${l.id}">${T('检查答案','Check answer')}</button><p id="answer-feedback4" role="status"></p>`:''}</section><section class="note4"><h2>${T('用自己的话解释','Explain it in your own words')}</h2><label for="note4">${T('记录输入、预测、读数和误差来源','Record input, prediction, measurement and possible error')}</label><textarea id="note4" rows="5">${E(UI4.notes[l.id]||'')}</textarea><button data-done="${l.id}">${UI4.done.includes(l.id)?T('✓ 已完成，可继续复习','✓ Completed — keep reviewing'):T('我已完成本课实验','I completed this lesson experiment')}</button><small>${T('这是自我记录，不代表工程资质。','This is a self-record, not an engineering qualification.')}</small></section></article><aside class="lesson-work4">${workbench4(lab,true)}</aside></div>`;}
function fields4(id,s){let k=LAB4[id][2],fields=STORY_META[k]?STORY_META[k].fields.map(f=>[f[0],f[2],f[3],f[4],f[5]]):({analog:[['v',5,1,12,.1],['r',1000,1,2000,1],['rm',1000,10,10000,10]],vision:[['threshold',128,0,255,1]],rl:[['episodes',100,1,500,1]],stencil:[['thickness',.12,.06,.3,.01],['aperture',.6,.1,1.5,.05]],reflow:[['peak',235,170,280,1],['dwell',50,0,150,1]],pcb:[['width',.3,.05,2,.05],['clearance',.25,.05,1,.05]]}[id]||[]);if(id==='pid')fields.push(['kd',0,0,1,.05]);if(id==='power')fields.push(['limit',20,0,50,1]);if(id==='meter')fields=fields.filter(f=>f[0]!=='r');return fields.map(([key,v,min,max,step])=>{if(s.p[key]===undefined)s.p[key]=v;let unit=FIELD4[key][2];if(['rc','analog'].includes(k)&&key==='r')unit='kΩ';return `<label class="parameter4">${label4(key)}<output data-value="${key}">${s.p[key]} ${unit}</output><input data-param="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${s.p[key]}" aria-label="${E(label4(key))}"></label>`;}).join('');}
function workbench4(id,embedded=false){if(!LAB4[id])id='circuit';let s=sim4(id),kind=LAB4[id][2];return `<section class="bench4" data-bench="${id}"><header><div><span class="overline">${T('操作 · 仿真 · 测量','OPERATE · SIMULATE · MEASURE')}</span><h2>${T(LAB4[id][0],LAB4[id][1])}</h2></div>${embedded?`<button data-lab="${id}">${T('展开操作台 ↗','Expand workbench ↗')}</button>`:''}${!embedded?`<select aria-label="${T('切换操作台','Select workbench')}" id="bench-select4">${Object.entries(LAB4).map(([k,v])=>`<option value="${k}" ${id===k?'selected':''}>${T(v[0],v[1])}</option>`).join('')}</select>`:''}</header><div class="bench-canvas4"><canvas width="900" height="420" aria-label="${T('实时模型，测量结果在下方文字同步显示','Live model; equivalent measurement text appears below')}"></canvas><div class="clock4" id="clock4">0.00 s</div></div><div class="measure4" id="measure4"></div><div class="transport4"><button data-sim="play">${s.run?T('暂停','Pause'):T('播放','Play')}</button><button data-sim="step">${T('单步','Step')}</button><button data-sim="reset">${T('复位','Reset')}</button>${['circuit','rc','thermal','pid'].includes(kind)?`<button data-sim="toggle">${kind==='pid'?T('切换扰动','Toggle disturbance'):T('切换开关 / 热源','Toggle switch / source')}</button>`:''}${id==='rl'?`<button data-sim="train">${T('训练策略','Train policy')}</button>`:''}</div><div class="parameters4">${fields4(id,s)}${id==='meter'?`<label>${T('测量档位','Measurement mode')}<select data-setting="mode"><option value="voltage" ${s.mode==='voltage'?'selected':''}>${T('电压','Voltage')}</option><option value="current" ${s.mode==='current'?'selected':''}>${T('电流','Current')}</option></select></label><label>${T('红笔插孔','Red lead jack')}<select data-setting="jack"><option value="voltage" ${s.jack==='voltage'?'selected':''}>VΩ</option><option value="current" ${s.jack==='current'?'selected':''}>mA</option></select></label><label>${T('表笔连接位置','Meter connection')}<select data-setting="place"><option value="source" ${s.place==='source'?'selected':''}>${T('并接电源','Across source')}</option><option value="series" ${s.place==='series'?'selected':''}>${T('串入支路','In series')}</option><option value="led" ${s.place==='led'?'selected':''}>${T('并接LED','Across LED')}</option></select></label>`:''}${id==='fault'?`<label>${T('注入故障','Inject a fault')}<select data-setting="place">${[['source','正常','Healthy'],['open','断路','Open circuit'],['reverse','反接LED','Reversed LED']].map(([v,z,e])=>`<option value="${v}" ${s.place===v?'selected':''}>${T(z,e)}</option>`).join('')}</select></label>`:''}</div><div class="explain4" id="explain4"></div><details class="model4"><summary>${T('模型边界与操作提示','Model limits and operating hints')}</summary><p>${T('同一操作台的控件、动画和读数使用同一个状态。页面中的计算是教学模型，不代替真实器件数据或安全验证。改变语言和主题不会复位实验；切换实验会保留参数。','Controls, animation and readings share one state within each workbench. These are teaching models, not replacements for component data or safety validation. Language and theme changes preserve the experiment; switching workbenches preserves parameters.')}</p><p>${id==='robot'?T('拖动十字目标，或使用X/Y滑块。两连杆各110 mm，未模拟碰撞与动力学。','Drag the target or use X/Y sliders. Both links are 110 mm; collisions and dynamics are not modeled.'):T('先暂停，修改一个条件，用单步观察变化。光点与协议动画为慢放示意。','Pause, change one condition, then step to observe it. Particle and protocol motion is a slow explanatory visualization.')}</p></details></section>`;}
function help4(){return `<div class="help-content4"><span class="overline">${T('帮助与指南','HELP & GUIDE')}</span><h1>${T('从这里开始，不用猜怎么操作','Start here — know what to do next')}</h1>${[[T('我是第一次学电路','I have never studied electronics'),T('从首页第1课开始。先看回路，再理解单位，完成例题，最后在同页操作台里改变一个参数。不要跳过万用表的插孔和串并联连接。','Begin with lesson 1. Trace the circuit, learn units, work through the example, then change one parameter in the same-page workbench. Do not skip meter jacks and series versus parallel connection.')],[T('怎么使用操作台','How to use the workbench'),T('滑块直接改变模型输入；读数和图像同步更新。暂停只停止时间推进，仍能改参数；单步推进0.1秒。CPU操作台每次单步执行一条指令。复位会恢复当前操作台默认值。','Sliders change model inputs and update readings and graphics. Pause stops time but allows parameter edits. Step advances 0.1 seconds; the CPU steps one instruction. Reset restores defaults for the current workbench.')],[T('怎么切换中英文和主题','Language and appearance'),T('顶部语言按钮切换整个应用的课程、帮助、控件与反馈。主题可选暖米橙、明亮和深色。个人笔记不会自动翻译。设置保存在本机浏览器。','The language button switches lessons, help, controls and feedback. Choose Warm, Light or Dark. Personal notes are not translated. Preferences are saved in the local browser.')],[T('记录与备份','Progress and backups'),T('笔记自动保存，课程完成是自我确认。导出备份会保存笔记、进度与偏好。换电脑、浏览器或文件位置前请导出；导入只恢复已知字段，不执行文件中的代码。','Notes save automatically and lesson completion is self-reported. Export saves notes, progress and preferences. Export before changing computer, browser or file location. Import accepts known data fields and never executes file content.')],[T('为什么动画没有自动播放','Why an animation may start paused'),T('如果系统设置了减少动态效果，动画默认暂停。点击播放可主动启动。网页切到后台时暂停推进时间，避免回来后模型突然跳过一大段。','If reduced motion is enabled, animations start paused. Press Play to opt in. Time does not advance while the page is hidden, avoiding a large jump when you return.')],[T('仿真可以直接用于真实硬件吗','Can I use the simulation as hardware validation?'),T('不能。LED压降、RC、热传递和一阶控制对象都做了简化。PCB、锡膏和回流页面仅检查明确列出的课堂条件，不是专业EDA或工艺认证。','No. LED drop, RC, heat transfer and the first-order control plant are simplified. PCB, paste and reflow workbenches check stated classroom criteria only; they are not professional EDA or process certification.')]].map(([a,b])=>`<section><h2>${a}</h2><p>${b}</p></section>`).join('')}</div>`;}
function notes4(){return `<h1>${T('我的学习记录','My learning record')}</h1><p>${UI4.done.length} / ${LESSONS.length} ${T('课程已标记完成','lessons marked complete')}</p>${LESSONS.filter(l=>UI4.notes[l.id]||UI4.done.includes(l.id)).map(l=>`<article class="note4"><button data-lesson="${l.id}">${E(title4(l))}</button><p>${E(UI4.notes[l.id]||T('本课暂无笔记','No note yet'))}</p></article>`).join('')||`<p>${T('在课程页写下第一次预测，这里就会出现你的记录。','Write your first prediction on a lesson page to see it here.')}</p>`}`;}
