function advance4(id,s,dt){if(['cpu','vision','rl','analog','stencil','reflow','pcb','fault'].includes(id)){s.t+=dt;if(id==='cpu'&&!s.cpu.halted&&Math.floor(s.t*2)>s.step){Models.cpuStep(s.cpu);s.step=Math.floor(s.t*2);}}else if(id==='pid'&&dt>0){s.t+=dt;let p=s.p,e=p.target-s.y,candidate=s.integral+e*dt,dy=(s.y-s.previousY)/dt;s.previousY=s.y;s.filteredD+=dt/(.05+dt)*(dy-s.filteredD);let raw=p.kp*e+p.ki*candidate-p.kd*s.filteredD,u=Math.max(-100,Math.min(100,raw));if(Math.abs(raw)<=100||raw*e<0)s.integral=candidate;s.y+=dt*(-s.y+u-s.d);if(!s.history.length||s.t-s.history[s.history.length-1][0]>=.025)s.history.push([s.t,s.y,p.target]);if(s.history.length>1200)s.history.shift();}else storyAdvance(s,dt);}
function mount4(){let el=document.querySelector('[data-bench]');if(!el){active4=null;return;}let id=el.dataset.bench,s=sim4(id);active4=id;let canvas=el.querySelector('canvas');if(id==='robot'){let dragging=false;canvas.style.touchAction='none';const move=e=>{let r=canvas.getBoundingClientRect();s.p.x=Math.round(Math.max(-220,Math.min(220,(e.clientX-r.left)/r.width*900-450)));s.p.y=Math.round(Math.max(-120,Math.min(220,290-(e.clientY-r.top)/r.height*420)));document.querySelectorAll('[data-param]').forEach(x=>{x.value=s.p[x.dataset.param];});updateValues4();paint4(id,s);};canvas.addEventListener('pointerdown',e=>{dragging=true;canvas.setPointerCapture(e.pointerId);move(e);});canvas.addEventListener('pointermove',e=>{if(dragging)move(e);});canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('pointercancel',()=>dragging=false);}last4=0;paint4(id,s);const tick=now=>{let dt=last4?Math.min(.05,(now-last4)/1000):0;last4=now;if(s.run&&!document.hidden){for(let j=0;j<5;j++)advance4(id,s,dt/5);paint4(id,s);}loop4=requestAnimationFrame(tick);};loop4=requestAnimationFrame(tick);}
function updateValues4(){if(!active4)return;let s=sim4(active4);document.querySelectorAll('[data-value]').forEach(el=>{let k=el.dataset.value,u=FIELD4[k][2];if(k==='r'&&['rc','analog'].includes(active4))u='kΩ';el.textContent=s.p[k]+' '+u;});}
