document.addEventListener('click',e=>{let b=e.target.closest('[data-go],[data-lesson],[data-lab],[data-client],[data-sim],[data-done],[data-check]');if(!b)return;e.preventDefault();if(b.dataset.go){nav4(b.dataset.go);return;}if(b.dataset.lesson){nav4('lesson',b.dataset.lesson);return;}if(b.dataset.lab){nav4('lab',b.dataset.lab);return;}if(b.dataset.client==='language'){UI4.lang=UI4.lang==='zh'?'en':'zh';save4();render4();return;}if(b.dataset.client==='export'){download4();return;}if(b.dataset.done){if(!UI4.done.includes(b.dataset.done))UI4.done.push(b.dataset.done);save4();render4();return;}if(b.dataset.check){let n=document.getElementById('answer4').value,q=CHECK4[b.dataset.check],ok=n!==''&&Number.isFinite(+n)&&Math.abs(+n-q[0])<=.03;document.getElementById('answer-feedback4').textContent=ok?T('正确。再用操作台验证你的推导。','Correct. Verify your reasoning in the workbench.'):T('再核对单位和公式。参考值约为 ','Check units and the equation. Reference value: ')+q[0];return;}if(b.dataset.sim&&active4){let id=active4,s=sim4(id),a=b.dataset.sim;if(a==='play')s.run=!s.run;if(a==='step'){s.run=false;if(id==='cpu')Models.cpuStep(s.cpu);else for(let i=0;i<10;i++)advance4(id,s,.01);}if(a==='toggle'){if(id==='pid')s.d=s.d?0:20;else s.on=!s.on;}if(a==='train'){s.rl=Models.qlearn(s.p.episodes,.2,.2);s.t=0;}if(a==='reset'){delete SIM4[id];render4();return;}paint4(id,s);}});
document.addEventListener('input',e=>{let el=e.target;if(el.dataset.param&&active4){let s=sim4(active4),k=el.dataset.param,v=Number(el.value);if(Number.isFinite(v)){s.p[k]=Math.max(+el.min,Math.min(+el.max,v));if(active4==='rl')s.rl=null;updateValues4();paint4(active4,s);}return;}if(el.id==='note4'){UI4.notes[UI4.id]=el.value.slice(0,20000);save4();}if(el.id==='course-search4'){let pos=el.selectionStart;UI4.search=el.value;render4();let n=document.getElementById('course-search4');n.focus();n.setSelectionRange(pos,pos);}});
document.addEventListener('change',async e=>{let el=e.target;if(el.id==='theme4'){UI4.theme=el.value;save4();document.documentElement.dataset.theme=UI4.theme;if(active4)paint4(active4,sim4(active4));}if(el.id==='bench-select4')nav4('lab',el.value);if(el.dataset.setting&&active4){sim4(active4)[el.dataset.setting]=el.value;paint4(active4,sim4(active4));}if(el.id==='import4'&&el.files?.[0]){try{let raw=JSON.parse(await el.files[0].text());if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error();let notes={},done=[];for(let l of LESSONS){if(typeof raw.notes?.[l.id]==='string')notes[l.id]=raw.notes[l.id].slice(0,20000);if(Array.isArray(raw.done)&&raw.done.includes(l.id))done.push(l.id);}UI4.notes=notes;UI4.done=done;if(['zh','en'].includes(raw.lang))UI4.lang=raw.lang;if(['warm','light','dark'].includes(raw.theme))UI4.theme=raw.theme;save4();render4();notice4(T('备份已导入','Backup imported'));}catch{notice4(T('文件不是有效的学习备份','This file is not a valid learning backup'));}}});
try{let [v,id]=decodeURIComponent(location.hash.slice(1)).split('/');if(['home','courses','lesson','lab','labs','atlas','projects','notes','sources','help'].includes(v)){UI4.view=v==='labs'?'lab':v;if(v==='lesson'&&LESSONS.some(l=>l.id===id))UI4.id=id;if(['lab','labs'].includes(v)){let key=LM4[id]||id;if(LAB4[key])UI4.lab=key;}}}catch{};
const PROJECT_EN4=[
['Stabilized gimbal','IMU, encoders and two-axis actuators','Attitude error → angle/speed loops → driver','Measure step response and disturbance rejection on a fixed rig before visual tracking.','Pinch points and driver overcurrent'],['Vision-guided arm','Joints, gripper, camera and calibration target','Detection → frame transform → IK → trajectory → grasp','Check frames and limits unloaded at low speed; measure error at several targets.','Collision, pinching and dropped objects'],['Drone test rig','Flight controller, IMU, motors/ESCs and receiver','Estimation → rate loop → allocation → ESC','Remove propellers to verify direction, failsafe, stop behavior and power logs.','Propellers, batteries and falls'],['Joint motor rig','Servo, gearbox, absolute encoder and CAN','Position/speed/torque modes with limits and command timeout','Use a restrained limited-power rig to verify direction, units and timeout.','High torque, heat and limits'],['Soft gripper','Compliant structure, actuator and force sensor','Position limit → contact detection → force limit','Repeat grasps on safe surrogate objects; measure peak force and success rate.','Pinch points, pressure and fatigue'],['Exoskeleton research rig','Actuator, encoder, IMU and foot pressure','State recognition → assistance strategy → independent safety monitor','Verify limits and power loss using non-human loads before qualified review.','Human injury, ethics and fault protection'],['EEG/EMG screen interaction','Public or synthetic data and screen task','Filtering → features → classification → low-risk feedback','Separate participants/sessions in evaluation and measure false triggers.','Privacy, artifacts and medical misinterpretation'],['Underwater ROV','Sealed enclosure, thrusters, leak/pressure sensors, camera and tether','Depth/attitude estimation → allocation → thrusters','Start with dry tests and shallow tethered checks; test leaks and communication loss.','Ingress, pressure, corrosion and tether'],['Tracked rover','Chassis, driver, encoders, IMU and range sensor','Speed loops → odometry → obstacle response','Measure straight travel, turning and stopping in a closed low-speed area.','Collision, pinch points and stall current'],['Quadruped / wheel-leg research','Joint actuators, IMU and contact sensing','Estimation → planning → whole-body control','Use simulation and restrained low-energy rigs; record failed recoveries.','Powerful joints and falls'],['Water-quality vessel','Hull, propulsion, GNSS and water sensors','Heading/position control and sampling schedule','Test tethered near shore; verify communication loss, retrieval and leaks.','Waterway rules, retrieval and pollution'],['AGV / AMR','Drive, LiDAR/camera and safety sensors','Localization → planning → local control → safe stop','Test localization loss, occlusion, moving obstacles and stopping distance.','Personnel collision and safety certification'],['Industrial vision inspection','Camera, lighting, lens and fixture','Trigger → acquire → detect → traceability','Use an independent defect set to measure misses, false alarms and cycle time.','Misclassification and dataset bias'],['Agricultural / rescue robot','Terrain chassis, multimodal sensors and communications','Perception → task planning → remote takeover','Define mud, slopes, lost-link and recovery scenarios in controlled testing.','People, environment and unpredictable terrain'],['Digital twin / industrial IoT','Gateway, sensors, logs and visualization','Acquisition → validation → model → alert','Test recorded replay, clock alignment, network recovery and false alarms.','Model mismatch, networks and permissions'],['Wearable device','Low-power MCU, IMU and environmental or physiological sensing','Acquire → process locally → wireless → interface','Measure battery life, wearing stability, false triggers and privacy behavior.','Body-worn battery, skin contact and personal data']];
function projects4(){return `<h1>${T('把学到的原理组成项目','Turn principles into projects')}</h1><p>${T('先完成对应基础课，再按分阶段验证推进。项目路线不是现成可直接运行的硬件方案。','Complete the linked foundations, then validate one stage at a time. These routes are not ready-to-run hardware designs.')}</p><div class="cards4">${PROJECTS.map((p,i)=>{let en=PROJECT_EN4[i];return `<article class="learn-card"><span>${p.level} · ${p.hours} h</span><h3>${E(T(p.name,en[0]))}</h3>${[[T('组成','Parts'),T(p.bom,en[1])],[T('控制链路','Control chain'),T(p.control,en[2])],[T('如何验证','Validation'),T(p.test,en[3])],[T('风险边界','Risks'),T(p.risk,en[4])]].map(([a,b])=>`<p><strong>${a}</strong><br>${E(b)}</p>`).join('')}<button data-lesson="${p.lesson}">${T('先学这一课','Start with this lesson')} →</button></article>`;}).join('')}</div>`;}

const ATLAS_EN4={
components:[['Resistor','Current limiting, division and sensing. Check resistance, power, tolerance and temperature coefficient. Measure resistance unpowered.'],['Capacitor','Energy storage, decoupling and filtering. Check capacitance, voltage, ESR, dielectric and polarity; discharge before handling.'],['Inductor / ferrite bead','Magnetic storage or high-frequency loss. Check inductance, saturation, DCR or frequency-dependent impedance; a bead is not an ideal inductor.'],['Diode','Directional conduction. Check reverse voltage, forward current, recovery and package polarity.'],['Schottky diode','Low-drop rectification. Check leakage and reverse voltage as well as forward drop.'],['Zener / TVS','Voltage regulation or transient clamping. Check operating voltage, clamp level, power and pulse energy; their time scales differ.'],['NPN / PNP transistor','Current-controlled switching or amplification. Verify base/collector/emitter order and limit base current.'],['N / P MOSFET','Gate-controlled conduction. Check VDS, RDS(on) at the actual VGS, gate charge and safe operating area. Threshold is not full enhancement.'],['Op-amp','Feedback amplification. Check input common-mode range, output swing, bandwidth, slew rate and stability.'],['Comparator','Threshold detection. Check input limits, delay and hysteresis. Open-drain outputs require a pull-up.'],['LDO','Linear regulation. Check dropout, dissipation and required capacitor range. Verify the exact pinout.'],['Buck / boost converter','Switching voltage conversion. Check input/output ranges, efficiency, ripple, loop stability and switching layout.'],['Optocoupler','Optical isolation. Check current-transfer ratio, isolation rating, speed and aging; verify board clearances.'],['Relay','Coil-operated contacts. Check coil rating, contact load type and lifetime. A DC coil often needs an appropriate clamp.'],['Fuse','Limits sustained fault energy. Check current, voltage, interrupt rating and time-current curve. Diagnose the cause before replacement.'],['Crystal / oscillator','Clock reference. Check frequency, load capacitance, ESR and temperature stability. Passive crystals differ from powered oscillators.'],['Connector','Removable interface. Check current, voltage, locking and pinout; matching appearance does not guarantee compatibility.'],['LED / segment display','Light indication. Limit current and check polarity, common-anode/common-cathode arrangement and multiplexed peak current.'],['Buzzer','Sound output. Active buzzers and passive transducers need different drive signals and current capability.'],['Button / encoder','Discrete input or position increments. Define pull resistors, debounce, counting and direction; account for contact bounce.']],
sensors:[['IMU','Angular rate and specific force. Calibrate stationary bias and scale; distinguish gravity from linear acceleration.'],['Magnetometer','Magnetic field. Calibrate hard-iron and soft-iron effects and keep away from motors and high-current wiring.'],['Pressure / underwater pressure','Pressure-derived altitude or depth. Check temperature drift, reference pressure, sealing and rated pressure.'],['Temperature / humidity','Environmental conditions. Consider response time, condensation, self-heating and installation position.'],['Gas / turbidity / water quality','Specific chemical or optical response. Check cross-sensitivity, aging, reference solutions and the actual measurement principle.'],['Light / color','Illuminance and spectral components. Source spectrum, windows, angle and white balance affect results.'],['Encoder / odometry','Angle or incremental position. Verify direction, counts and gear ratio; wheel slip causes odometry drift.'],['Strain / force / torque','Deformation or integrated force sensing. Check zero, temperature compensation, load direction, overload and mounting stiffness.'],['Current / voltage','Shunt, magnetic or divider measurements. Check common-mode range, isolation, dissipation and bandwidth.'],['Ultrasonic / ToF / point range','Time-of-flight distance. Check blind zones, reflectivity, angle and cross-talk; one distance is not complete obstacle awareness.'],['LiDAR','Scanned distances. Check scan rate, timestamps, reflectivity and extrinsic calibration.'],['RGB / IR / stereo / depth camera','Different imaging and depth modalities. Check calibration, exposure, baseline, lighting and synchronization; modalities are not interchangeable.'],['Optical flow','Local image motion. Depends on texture, scale and height; not an absolute global position measurement.'],['GNSS / GPS / RTK','Satellite-based positioning. Check occlusion, multipath, antenna and correction-link availability.'],['UWB','Radio ranging. Check anchor coordinates, non-line-of-sight bias and synchronization.'],['Tactile / flexible / foot pressure','Contact distribution and deformation. Check hysteresis, drift, force range and mounting preload.'],['Limit / leak switch','End-position or fluid detection. Define normally-open/closed logic, fault detection and contamination behavior.'],['EEG / EMG / ECG','Neural, muscle or cardiac activity. Use qualified isolated acquisition and ethical review for human-connected work; not a medical diagnosis.'],['Underwater acoustic range','Acoustic travel-time measurement. Temperature, salinity, depth, reflection, latency and multipath affect interpretation.']],
protocols:[['UART','Asynchronous serial frames: start, least-significant-first data, optional parity and stop. Match frame format, rate, levels and reference ground.'],['I²C','Usually open-drain with pull-ups. START, address/direction, ACK, data and STOP. Check address convention, capacitance and acknowledgment.'],['SPI','Clocked shifting while chip-select is active. Match CPOL/CPHA, bit order, chip-select timing and voltage levels.'],['CAN / CAN-FD','Differential multi-node arbitration. Check bit timing, termination, error counters and node compatibility.'],['RS-232','Electrical interface different from MCU logic levels. Use a suitable transceiver, not a direct 3.3 V GPIO connection.'],['RS-485','Differential multipoint electrical interface. Check polarity naming, bias, termination and driver enable; upper protocols vary.'],['USB','Version-appropriate PHY, enumeration, endpoints and transfers. Check cable data capability, power, descriptors and drivers.'],['Ethernet','MAC/PHY and cable rules carry higher-level packets. Check link, addressing, subnet, loss and latency.'],['Wi-Fi / BLE','Wireless connection or advertising/service mechanisms. Check signal, pairing, reconnects and peak power consumption.'],['TCP / UDP','TCP is a byte stream; UDP uses datagrams. Define application message boundaries, retries, ordering and loss handling.'],['MQTT / HTTP','Publish/subscribe topics or request/response. Check authentication, timeout, idempotence and reconnect behavior.'],['Modbus RTU / TCP','Register-oriented messages over serial or TCP. Check numbering convention, byte order and RTU timing/CRC.'],['PWM / PPM','Pulse width or multichannel pulse sequences. Check units, period, update rate and lost-link behavior.'],['DShot','Digital ESC commands with version-specific rates and checks. Verify controller/ESC support with propellers removed.'],['CRSF / SBUS','Digital remote-control channels and telemetry. Check inversion, voltage, rate, frame format and failsafe.'],['ROS 2 DDS','Discovery, typed topics and QoS. Check domain ID, networking, clock and compatible QoS settings.']]
};
function atlas4(){return `<h1>${T('元件、传感器与协议图鉴','Components, sensors and protocols')}</h1><p>${T('先理解用途，再核对型号、引脚、额定值和测量条件。这里的条目不是具体器件数据手册。','Understand the purpose, then verify model, pinout, ratings and measurement conditions. These entries do not replace part-specific datasheets.')}</p>${[['components',COMPONENTS,'常用元件','Components'],['sensors',SENSORS,'传感器','Sensors'],['protocols',PROTOCOLS,'接口与协议','Interfaces and protocols']].map(([key,rows,z,e])=>`<h2>${T(z,e)} · ${rows.length}</h2><div class="cards4">${rows.map((row,i)=>`<article class="learn-card"><h3>${E(T(row[0],ATLAS_EN4[key][i][0]))}</h3><p>${E(T(row.slice(1).join('。'),ATLAS_EN4[key][i][1]))}</p></article>`).join('')}</div>`).join('')}`;}

